budget = {"Rent": 200000, "Ingredients": 150000, "Salaries": 250000, "Utilities": 150000}
actual = {"Rent": 200000, "Ingredients": 150000, "Salaries": 250000, "Utilities": 180000}

for item in budget:
    difference = actual[item] - budget[item]
    if difference > 0:
        note = "zyada kharch"
    elif difference < 0:
        note = "bachat"
    else:
        note = "budget ke mutabiq"
    print(f"{item}: budget Rs. {budget[item]:,}, asal Rs. {actual[item]:,} -> {note}")

total_budget = sum(budget.values())
total_actual = sum(actual.values())
print(f"Kul budget: Rs. {total_budget:,} | Kul asal kharcha: Rs. {total_actual:,}")
if total_actual > total_budget:
    print(f"Overspending (zyada kharch): Rs. {total_actual - total_budget:,}")
else:
    print(f"Bachat: Rs. {total_budget - total_actual:,}")
